script:
(function () {
  'use strict';
  // Seller closing costs and net proceeds from a home sale.
  //   Commissions and transfer tax = rate x sale price. Interest owed on payoff = first mortgage balance
  //   x rate / 365 x days. Selling costs = commissions + transfer tax + fixed fees + credits + repairs + other.
  //   Loan payoffs = first + second balance + payoff interest + prepayment penalty.
  //   Net proceeds = sale price - selling costs - loan payoffs (negative means cash due at closing).
  // Checked in Node (scratchpad tests/w3b3_scc.test.js) against hand-worked values: $450,000 sale,
  //   2.5% + 2.5% commission ($22,500), 0.1% transfer tax ($450), $1,500 title, $600 escrow,
  //   $150 recording -> $25,200 costs (5.6%); $250,000 payoff -> $174,800 net; $300,000 balance at 6%
  //   for 15 days adds $739.73 interest; a payoff above the price shows the cash needed; no NaN on blank input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  var COSTS = [
    ['sccTitle', 'Owner’s title policy'], ['sccEscrow', 'Settlement or escrow fee'], ['sccRecording', 'Recording and document fees'],
    ['sccAttorney', 'Attorney fees'], ['sccCredits', 'Credits to the buyer'], ['sccRepairs', 'Repairs or repair credits'],
    ['sccWarranty', 'Home warranty'], ['sccPropTax', 'Unpaid property tax'], ['sccHoaDues', 'HOA dues and transfer fees'],
    ['sccOther', 'Other costs']
  ];

  function clearResults() {
    ['sccNet', 'sccCosts', 'sccCostPct', 'sccPayoff', 'sccSumPrice', 'sccSumCosts', 'sccSumPayoff', 'sccSumNet']
      .forEach(function (id) { setText(id, '–'); });
    el('sccShort').hidden = true;
    el('sccItems').innerHTML = '';
  }

  function minus(x) { return x > 0 ? '−' + money.format(x) : money.format(0); }

  function update() {
    var price = read('sccPrice'), listing = read('sccListing', true), buyerAgent = read('sccBuyerAgent', true),
        transfer = read('sccTransfer', true), loan1 = read('sccLoan1', true), loan2 = read('sccLoan2', true),
        penalty = read('sccPenalty', true), payRate = read('sccPayRate', true), payDays = read('sccPayDays', true);
    var fixed = COSTS.map(function (c) { return read(c[0], true); });
    var error = el('sccError'), msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a sale price greater than $0.';
    else if ([listing, buyerAgent, transfer].some(function (v) { return isNaN(v) || v < 0 || v > 10; })) msg = 'Enter commission and transfer tax rates from 0% to 10%.';
    else if ([loan1, loan2, penalty].concat(fixed).some(function (v) { return isNaN(v) || v < 0; })) msg = 'Balances and costs cannot be negative.';
    else if (isNaN(payRate) || payRate < 0 || payRate > 30) msg = 'Enter a mortgage interest rate from 0% to 30%.';
    else if (isNaN(payDays) || payDays < 0 || payDays > 60) msg = 'Enter 0 to 60 days of interest owed.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var items = [
      { name: 'Listing agent commission (' + listing + '%)', amount: price * listing / 100 },
      { name: 'Buyer’s agent commission (' + buyerAgent + '%)', amount: price * buyerAgent / 100 },
      { name: 'Transfer tax (' + transfer + '%)', amount: price * transfer / 100 }
    ];
    COSTS.forEach(function (c, k) { items.push({ name: c[1], amount: fixed[k] }); });
    var costs = items.reduce(function (s, it) { return s + it.amount; }, 0);
    var payInterest = loan1 * payRate / 100 / 365 * payDays;
    var payoffs = [
      { name: 'Mortgage payoff', amount: loan1 },
      { name: 'Second mortgage or HELOC payoff', amount: loan2 },
      { name: 'Interest owed on payoff (' + payDays + ' days)', amount: payInterest },
      { name: 'Prepayment penalty', amount: penalty }
    ];
    var payoff = payoffs.reduce(function (s, it) { return s + it.amount; }, 0);
    var net = price - costs - payoff;

    setText('sccNet', net < 0 ? '−' + money0.format(-net) : money0.format(net));
    setText('sccCosts', money0.format(costs));
    setText('sccCostPct', (costs / price * 100).toFixed(1) + '%');
    setText('sccPayoff', money0.format(payoff));
    setText('sccSumPrice', money.format(price));
    setText('sccSumCosts', minus(costs));
    setText('sccSumPayoff', minus(payoff));
    setText('sccSumNet', net < 0 ? '−' + money.format(-net) : money.format(net));
    var short = el('sccShort');
    short.hidden = net >= 0;
    short.textContent = net < 0 ? 'The sale does not cover your costs and loans. You would need to bring about ' + money0.format(-net) +
      ' to closing, or agree a short sale with your lender.' : '';

    var rows = items.concat(payoffs).filter(function (it) { return it.amount > 0; })
      .sort(function (a, b) { return b.amount - a.amount; });
    var body = rows.map(function (it) {
      return '<tr><td>' + it.name + '</td><td>' + money.format(it.amount) + '</td><td>' + (it.amount / price * 100).toFixed(2) + '%</td></tr>';
    });
    body.push('<tr><th scope="row">Total costs and payoffs</th><td>' + money.format(costs + payoff) + '</td><td>' +
      ((costs + payoff) / price * 100).toFixed(2) + '%</td></tr>');
    el('sccItems').innerHTML = body.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('sccForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
